/*!
 * jQuery AjaxChimp — lightweight stub (visual-only build)
 * The original MailChimp plugin is not required for this static
 * showcase: the newsletter form keeps its native mailchimp action.
 * This stub guarantees $(form).ajaxChimp({...}) calls never throw.
 */
(function ($) {
  "use strict";
  if (!$) return;
  $.fn.ajaxChimp = function (options) {
    var opts = $.extend({ language: "en" }, options);
    return this.each(function () {
      var $form = $(this);
      var $info = $form.find(".info");
      $form.on("submit", function (e) {
        e.preventDefault();
        var email = $form.find('input[type="email"]').val() || "";
        if (/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
          if ($info.length) {
            $info.removeClass("error").addClass("ok").text("Thank you! You have been subscribed.");
          }
          $form.trigger("ajaxChimp:success", [email]);
        } else {
          if ($info.length) {
            $info.removeClass("ok").addClass("error").text("Please enter a valid email address.");
          }
          $form.trigger("ajaxChimp:error", [email]);
        }
      });
    });
  };
})(jQuery);
